'use strict';
window.MatModules=(()=>{
  const cfg={
    materials:{roleLabel:'Matériels',eyebrow:'PARC MATÉRIEL',title:'Inventaire du matériel',description:'Gérez les références, seuils et états opérationnels.',canCreate:['ADMIN','STOREKEEPER'],api:'/api/materials'},
    movements:{roleLabel:'Mouvements',eyebrow:'SUIVI DU STOCK',title:'Mouvements de stock',description:'Historique filtrable des entrées, sorties et transferts.',canCreate:['ADMIN','STOREKEEPER'],api:'/api/movements'},
    allocations:{roleLabel:'Dotations',eyebrow:'AFFECTATIONS',title:'Dotations aux services',description:'Créez les services bénéficiaires et attribuez-leur le matériel du stock.',canCreate:['ADMIN','STOREKEEPER'],api:'/api/allocations'},
    maintenance:{roleLabel:'Maintenance',eyebrow:'SUIVI TECHNIQUE',title:'Journal de maintenance',description:'Planifiez une intervention ou démarrez-la immédiatement, puis suivez les pièces utilisées.',canCreate:['ADMIN','MAINTAINER'],api:'/api/maintenance'},
    supervision:{roleLabel:'Supervision',eyebrow:'PILOTAGE DES ÉQUIPES',title:'Équipes et évaluations',description:'Statistiques globales et notation journalière des magasiniers et maintenanciers.',canCreate:[],api:'/api/supervision/overview'},
    audit:{roleLabel:'Journal d’audit',eyebrow:'TRAÇABILITÉ',title:'Journal complet des actions',description:'Historique en lecture seule des actions enregistrées par Mat-Manage.',canCreate:[],api:'/api/audit-logs'},
    users:{roleLabel:'Utilisateurs',eyebrow:'ADMINISTRATION',title:'Comptes utilisateurs',description:'Gérez les rôles, accès et enrôlement MFA.',canCreate:['ADMIN'],api:'/api/users'},
    reports:{roleLabel:'Rapports',eyebrow:'PILOTAGE',title:'Rapports & statistiques',description:'Synthèses d’activité et de disponibilité du parc.',api:'/api/dashboard'}
  };
  let kind,role,rows=[],lookups={};
  const esc=MatApi.escape;
  function dateInputValue(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
  async function bootstrap(){const page=cfg[kind];try{const profile=(await MatApi.request('/api/profile')).profile;MatApi.setPreferenceScope(profile.user_id);role=profile.role_code;MatDashboard.renderNav(role,`${kind}.html`);document.querySelector('#sidebar-name').textContent=profile.full_name;document.querySelector('#sidebar-role').textContent=profile.role_name;if(profile.avatar_url){const img=document.querySelector('#sidebar-avatar');img.src=profile.avatar_url;img.alt='Avatar'}document.querySelector('#logout').addEventListener('click',logout);document.querySelector('#breadcrumb').textContent=page.roleLabel;document.querySelector('#page-eyebrow').textContent=page.eyebrow;document.querySelector('#page-title').textContent=page.title;document.querySelector('#page-description').textContent=page.description;
    const canCreate=(page.canCreate||[]).includes(role);document.querySelector('#create-record').hidden=!canCreate;if(kind==='movements'&&role==='MAINTAINER')document.querySelector('#page-description').textContent='Consultez les entrées, sorties et transferts pour vérifier la disponibilité des pièces.';document.querySelector('#create-record').textContent=`＋ ${kind==='materials'?'Ajouter un matériel':kind==='users'?'Créer un utilisateur':kind==='suppliers'?'Ajouter un fournisseur':kind==='orders'?'Nouvelle commande':kind==='maintenance'?'Nouvelle intervention':kind==='allocations'?'Créer une dotation':'Enregistrer un mouvement'}`;document.querySelector('#create-record').addEventListener('click',openCreate);document.querySelector('#export').addEventListener('click',exportCsv);document.querySelector('#apply-filters').addEventListener('click',load);document.querySelector('#search').addEventListener('input',()=>draw(rows));
      const serviceButton=document.querySelector('#create-service');if(serviceButton){serviceButton.hidden=kind!=='allocations'||!['ADMIN','STOREKEEPER'].includes(role);serviceButton.addEventListener('click',createService)}
      if(kind==='users') loadSettings();if(kind==='audit'){document.querySelector('#filter-one').innerHTML='<option value="">Tous les utilisateurs</option>';MatApi.request('/api/users').then(data=>{document.querySelector('#filter-one').innerHTML='<option value="">Tous les utilisateurs</option>'+data.users.map(u=>`<option value="${u.user_id}">${esc(u.full_name)} · ${esc(u.matricule)}</option>`).join('')}).catch(error=>showMessage(error.message,true))}
      if(kind==='materials'){const group=document.querySelector('#summary-group'),search=document.querySelector('#summary-search'),stockSearch=document.querySelector('#stock-organization-search');group.addEventListener('change',()=>{search.hidden=group.value!=='designation';loadMaterialSummary()});search.addEventListener('input',loadMaterialSummary);stockSearch?.addEventListener('input',loadStockOrganization);loadMaterialSummary()}
      const today=new Date(),from=new Date();from.setDate(today.getDate()-29);document.querySelector('#date-from').value=dateInputValue(from);document.querySelector('#date-to').value=dateInputValue(today);
      lookups.categories=(await MatApi.request('/api/categories')).categories;lookups.locations=(await MatApi.request('/api/locations')).locations;lookups.materials=(await MatApi.request('/api/materials')).materials;
      lookups.services=(await MatApi.request('/api/services')).services;
      if(kind==='materials'){document.querySelector('#date-from').hidden=true;document.querySelector('#date-to').hidden=true;document.querySelector('#filter-one').innerHTML='<option value="">Toutes catégories</option>'+lookups.categories.map(c=>`<option value="${c.category_id}">${esc(c.category_name)}</option>`).join('');document.querySelector('#filter-two').innerHTML='<option value="">Tous les statuts</option><option value="AVAILABLE">Disponible</option><option value="IN_MAINTENANCE">Maintenance</option><option value="DAMAGED">Endommagé</option><option value="RETIRED">Retiré</option>'}
      if(['movements','maintenance','allocations'].includes(kind)){document.querySelector('#filter-one').innerHTML=kind==='movements'?'<option value="">Tous mouvements</option><option value="IN">Entrées</option><option value="OUT">Sorties</option><option value="TRANSFER">Transferts</option>':kind==='maintenance'?'<option value="">Tous états</option><option value="PLANNED">Planifiée</option><option value="IN_PROGRESS">En cours</option><option value="COMPLETED">Terminée</option><option value="CANCELLED">Annulée</option>':kind==='orders'?'<option value="">Tous états</option><option value="DRAFT">Brouillon</option><option value="SENT">Envoyée</option><option value="CONFIRMED">Confirmée</option><option value="RECEIVED">Réceptionnée</option><option value="CANCELLED">Annulée</option>':kind==='quotes'?'<option value="">Tous états</option><option value="DRAFT">Brouillon</option><option value="SENT">Envoyée</option><option value="PARTIALLY_ANSWERED">Partielle</option><option value="ANSWERED">Répondue</option><option value="CANCELLED">Annulée</option>':'<option value="">Tous services</option>'+lookups.services.map(s=>`<option value="${s.service_id}">${esc(s.service_name)}</option>`).join('');document.querySelector('#filter-two').hidden=true}
      if(['suppliers','users','audit'].includes(kind)){document.querySelector('#date-from').hidden=true;document.querySelector('#date-to').hidden=true;document.querySelector('#filter-two').hidden=true;if(kind==='users')document.querySelector('#filter-one').innerHTML='<option value="">Tous les rôles</option><option value="ADMIN">Administrateur</option><option value="STOREKEEPER">Magasinier</option><option value="MAINTAINER">Maintenancier</option><option value="SUPERVISOR">Superviseur</option>';else if(kind==='suppliers')document.querySelector('#filter-one').hidden=true}
      if(kind==='reports'){document.querySelector('#search').hidden=true;document.querySelector('#filter-one').hidden=true;document.querySelector('#filter-two').hidden=true;document.querySelector('#period-summary-card').hidden=false}
      else document.querySelector('#period-summary-card').hidden=false;await load();
    }catch(error){showMessage(error.message,true)}}
  async function logout(){try{await MatApi.request('/api/auth/logout',{method:'POST',body:{}})}finally{location.assign('/login.html')}}
  function showMessage(text,error=false){const node=document.querySelector('#message');node.textContent=text;node.hidden=false;node.classList.toggle('error',error);setTimeout(()=>node.hidden=true,5000)}
  function queryUrl(){const url=new URLSearchParams();const q=document.querySelector('#search').value.trim();if(q)url.set('q',q);const first=document.querySelector('#filter-one').value,second=document.querySelector('#filter-two').value;if(kind==='materials'){if(first)url.set('categoryId',first);if(second)url.set('status',second)}else if(['movements','maintenance','orders','allocations','quotes'].includes(kind)){if(kind==='movements'&&first)url.set('type',first);if(kind==='maintenance'&&first)url.set('status',first);if(kind==='orders'&&first)url.set('status',first);if(kind==='quotes'&&first)url.set('status',first);if(kind==='allocations'&&first)url.set('serviceId',first);if(!document.querySelector('#date-from').hidden){if(document.querySelector('#date-from').value)url.set('from',document.querySelector('#date-from').value);if(document.querySelector('#date-to').value)url.set('to',document.querySelector('#date-to').value)}}else if(kind==='users'&&first)url.set('role',first);else if(kind==='audit'&&first)url.set('userId',first);if(kind==='supervision'){if(document.querySelector('#date-from').value)url.set('from',document.querySelector('#date-from').value);if(document.querySelector('#date-to').value)url.set('to',document.querySelector('#date-to').value);if(q)url.set('q',q)}if(kind==='suppliers')url.set('active','all');return `${cfg[kind].api}${url.size?'?'+url:''}`}
  async function load(){try{if(kind==='reports'){const from=document.querySelector('#date-from').value,to=document.querySelector('#date-to').value;const report=await MatApi.request(`/api/dashboard?from=${from}&to=${to}`);rows=report;drawReports(report);return}const result=await MatApi.request(queryUrl());rows=result.materials||result.movements||result.allocations||result.maintenance||result.users||result.personnel||result.logs||result.reviews||[];draw(rows);if(kind==='supervision')drawOversight(result);if(kind==='audit')document.querySelector('#period-summary').textContent='Journal en lecture seule : utilisateur, action, objet, date et contexte sont conservés.';if(kind==='materials'){await loadLocations();await loadStockOrganization()}}catch(error){showMessage(error.message,true)}}
  function setTable(headers){document.querySelector('#table-head').innerHTML=headers.map(h=>`<th>${h}</th>`).join('')}
  async function loadLocations(){const body=document.querySelector('#locations-body');if(!body)return;try{const result=await MatApi.request('/api/locations');lookups.locations=result.locations||[];const canAddStock=['ADMIN','STOREKEEPER'].includes(role);body.innerHTML=lookups.locations.length?lookups.locations.map(location=>`<tr><td><b>${esc(location.location_code)}</b></td><td>${esc(location.location_name)}</td><td>${esc(location.category_name||'Emplacement historique')}</td><td>${canAddStock?`<button type="button" class="btn btn-small add-stock-to-location" data-id="${location.location_id}" data-name="${esc(location.location_name)}">＋ Ajouter du matériel</button>`:'Emplacement de stock'}</td></tr>`).join(''):`<tr><td colspan="4" class="empty-state">Aucun emplacement disponible.</td></tr>`;body.querySelectorAll('.add-stock-to-location').forEach(button=>button.addEventListener('click',()=>addStockToLocation(button)))}catch(error){body.innerHTML='<tr><td colspan="4" class="empty-state">Impossible de charger les emplacements.</td></tr>';showMessage(error.message,true)}}
  async function loadStockOrganization(){const body=document.querySelector('#stock-organization-body');if(!body)return;try{const q=document.querySelector('#stock-organization-search')?.value.trim()||'',result=await MatApi.request(`/api/stock-organization?q=${encodeURIComponent(q)}`),items=result.stockOrganization||[];body.innerHTML=items.length?items.map(item=>`<tr><td><b>${esc(item.material_code)}</b></td><td>${esc(item.designation)}</td><td>${esc(item.location_code||'—')}</td><td>${esc(item.location_name||'Aucun emplacement')}</td><td>${item.quantity}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">Aucun matériel ou emplacement ne correspond à la recherche.</td></tr>'}catch(error){body.innerHTML='<tr><td colspan="5" class="empty-state">Impossible de charger l’organisation du stock.</td></tr>';showMessage(error.message,true)}}
  async function addStockToLocation(button){try{const response=await MatApi.request('/api/materials'),materials=response.materials||[];if(!materials.length){showMessage('Créez d’abord une fiche matériel avant de l’ajouter à un emplacement.',true);return}const options=materials.map(material=>`<option value="${material.material_id}">${esc(material.material_code)} · ${esc(material.designation)}</option>`).join('');const content=`<p class="summary-text">Cette entrée augmentera le stock disponible à « ${esc(button.dataset.name)} » et sera inscrite dans l’historique des mouvements.</p><div class="form-grid">${select('Matériel','materialId',options)}<div class="field"><label for="f-quantity">Quantité reçue</label><input id="f-quantity" name="quantity" type="number" min="0.01" step="0.01" value="1" required></div>${field('Référence du document (facultative)','documentReference','Bon de livraison','text',false)}${field('Note (facultative)','notes','Détail de la réception','text',false)}</div>`;openModal(`Ajouter du matériel · ${button.dataset.name}`,content,async data=>{await MatApi.request('/api/movements',{method:'POST',body:{type:'IN',materialId:Number(data.materialId),quantity:Number(data.quantity),destinationLocationId:Number(button.dataset.id),documentReference:data.documentReference||null,notes:data.notes||null}});MatApi.toast('Entrée de stock enregistrée dans cet emplacement.');await load()})}catch(error){showMessage(error.message,true)}}
  async function createService(){openModal('Créer un service',`<div class="form-grid">${field('Code service','serviceCode','Ex. DAF')}${field('Nom du service','serviceName','Direction administrative')}${field('Description','description','Description du service','text',false)}</div>`,async data=>{await MatApi.request('/api/services',{method:'POST',body:data});await lookupsForCreate();const filter=document.querySelector('#filter-one');if(kind==='allocations'&&filter){const selected=filter.value;filter.innerHTML='<option value="">Tous les services</option>'+lookups.services.map(service=>`<option value="${service.service_id}">${esc(service.service_name)}</option>`).join('');filter.value=selected}MatApi.toast('Service créé. Il est maintenant disponible pour les dotations.')})}
  async function loadMaterialSummary(){try{const group=document.querySelector('#summary-group')?.value||'category',q=document.querySelector('#summary-search')?.value||'',result=await MatApi.request(`/api/material-summaries?groupBy=${group}&q=${encodeURIComponent(q)}`);document.querySelector('#summary-body').innerHTML=result.summaries.map(row=>`<tr><td>${esc(row.label)}</td><td>${row.references_count}</td><td>${row.quantity}</td></tr>`).join('')||'<tr><td colspan="3">Aucune donnée pour cette recherche.</td></tr>'}catch(error){showMessage(error.message,true)}}
  async function loadSettings(){try{const result=await MatApi.request('/api/settings'),enabled=result.settings.account_creation_enabled==='1';let panel=document.querySelector('#account-settings');if(!panel){panel=document.createElement('section');panel.id='account-settings';panel.className='card';panel.innerHTML='<div class="card-body"><h2>Paramètres des comptes</h2><label><input type="checkbox" id="account-creation-enabled"> Autoriser la création de comptes depuis la page d’inscription</label> <button class="btn btn-primary" id="save-account-settings">Enregistrer</button></div>';document.querySelector('#module-kpis').after(panel)}panel.querySelector('#account-creation-enabled').checked=enabled;panel.querySelector('#save-account-settings').onclick=async()=>{try{await MatApi.request('/api/settings',{method:'PATCH',body:{accountCreationEnabled:panel.querySelector('#account-creation-enabled').checked}});MatApi.toast('Paramètres enregistrés.')}catch(error){showMessage(error.message,true)}}}catch(error){showMessage(error.message,true)}}
  function showRecord(record){const values=Object.entries(record).filter(([key])=>!['password_hash','totp_secret_enc'].includes(key));const body=`<div class="form-grid">${values.map(([key,value])=>`<div class="field"><label>${esc(key.replaceAll('_',' '))}</label><input readonly value="${esc(value==null?'':String(value))}"></div>`).join('')}</div>`;openModal('Caractéristiques',body,async()=>{});document.querySelector('#module-form [type="submit"]').hidden=true}
  function draw(data){const b=document.querySelector('#table-body');let headers=[],body='';
    if(kind==='materials'){headers=['CODE','DÉSIGNATION','CATÉGORIE','QUANTITÉ','SEUIL','EMPLACEMENTS','STATUT'];body=data.map(m=>{const status=Number(m.below_minimum)&&m.operational_status==='AVAILABLE'?'Stock faible':({AVAILABLE:'Disponible',IN_MAINTENANCE:'Maintenance',DAMAGED:'Endommagé',RETIRED:'Retiré'}[m.operational_status]||m.operational_status);const statusCell=(role==='ADMIN'||role==='STOREKEEPER')?`<select class="filter-control status-select" data-id="${m.material_id}"><option value="AVAILABLE" ${m.operational_status==='AVAILABLE'?'selected':''}>${Number(m.below_minimum)?'Disponible · stock faible':'Disponible'}</option><option value="IN_MAINTENANCE" ${m.operational_status==='IN_MAINTENANCE'?'selected':''}>Maintenance</option><option value="DAMAGED" ${m.operational_status==='DAMAGED'?'selected':''}>Endommagé</option><option value="RETIRED" ${m.operational_status==='RETIRED'?'selected':''}>Retiré</option></select>`:`<span class="status info">${esc(status)}</span>`;return `<tr class="detail-row" data-record="${esc(JSON.stringify(m))}"><td><b>${esc(m.material_code)}</b></td><td>${esc(m.designation)}<br><small class="muted-small">${esc(m.brand||'')} ${esc(m.model||'')}</small></td><td>${esc(m.category_name)}</td><td>${m.total_quantity}</td><td>${m.minimum_stock}</td><td>${esc(m.locations||'—')}</td><td>${statusCell}</td></tr>`}).join('')}
    if(kind==='movements'){headers=['DATE','RÉFÉRENCE','TYPE','MATÉRIEL','QUANTITÉ','EMPLACEMENT','AGENT / DESTINATAIRE'];body=data.map(m=>`<tr><td>${fmt(m.movement_date)}</td><td><b>${esc(m.movement_number)}</b></td><td>${status(m.movement_type)}</td><td>${esc(m.designation)}</td><td>${m.quantity}</td><td>${esc(m.destination_location||m.source_location||'')}</td><td>${esc(m.service_name||m.recipient_name||m.performed_by||'')}</td></tr>`).join('')}
    if(kind==='allocations'){headers=['DATE','N° DOTATION','SERVICE','BÉNÉFICIAIRE','MATRICULE / CNI','MATÉRIEL','QUANTITÉ','DÉCHARGE'];body=data.map(a=>`<tr><td>${fmt(a.allocation_date)}</td><td><b>${esc(a.allocation_number)}</b></td><td>${esc(a.service_name)}</td><td>${esc(a.recipient_name)}</td><td>${a.recipient_id_number?`${a.recipient_id_type==='CNI'?'CNI':'Matricule'} · ${esc(a.recipient_id_number)}`:'—'}</td><td>${esc(a.designation)}</td><td>${a.quantity}</td><td>${esc(a.receipt_reference||'—')}</td></tr>`).join('')}
    if(kind==='maintenance'){headers=['DATE','CODE MATÉRIEL','DÉSIGNATION','DIAGNOSTIC','ACTIONS POSÉES','COMMENTAIRES','CONCLUSION','MATRICULE MAINT.','NOM MAINTENANCIER','DÉPARTEMENT','ÉTAT','ACTIONS'];body=data.map(m=>`<tr class="maintenance-row" data-id="${m.maintenance_id}" tabindex="0"><td>${fmtDateTime(m.scheduled_at)}<br><small>${m.started_at?`Début : ${fmtDateTime(m.started_at)}`:''}${m.completed_at?`<br>Fin : ${fmtDateTime(m.completed_at)}`:''}</small></td><td><b>${esc(m.material_code)}</b></td><td>${esc(m.designation)}</td><td class="cell-wrap">${esc(m.diagnosis||'—')}</td><td class="cell-wrap">${esc(m.actions_taken||'—')}</td><td class="cell-wrap">${esc(m.comments||'—')}</td><td>${m.conclusion?status(m.conclusion==='FUNCTIONAL'?'Fonctionnel':'Défectueux'):'—'}</td><td>${esc(m.technician_matricule||'—')}</td><td>${esc(m.technician||'—')}</td><td>${esc(m.technician_department||'—')}</td><td>${status(({PLANNED:'Planifiée',IN_PROGRESS:'En cours',COMPLETED:'Terminée',CANCELLED:'Annulée'})[m.status]||m.status)}</td><td><button class="btn btn-small maintenance-details" data-id="${m.maintenance_id}">Détails</button> ${['PLANNED','IN_PROGRESS'].includes(m.status)?`<button class="btn btn-small btn-primary maintenance-execute" data-id="${m.maintenance_id}">${m.status==='PLANNED'?'Exécuter':'Terminer'}</button><button class="btn btn-small maintenance-parts" data-id="${m.maintenance_id}" data-number="${esc(m.maintenance_number)}" data-status="${m.status}">Pièces</button>`:''}</td></tr>`).join('')}
    if(kind==='suppliers'){headers=['FOURNISSEUR','CONTACT','SPÉCIALITÉ','E-MAIL','TÉLÉPHONE','ÉTAT'];body=data.map(s=>`<tr><td><b>${esc(s.supplier_name)}</b></td><td>${esc(s.contact_name||'—')}</td><td>${esc(s.specialty||'—')}</td><td>${esc(s.email||'—')}</td><td>${esc(s.phone||'—')}</td><td>${status(s.is_active?'Actif':'Inactif')}</td></tr>`).join('')}
    if(kind==='orders'){headers=['DATE','N° COMMANDE','FOURNISSEUR','ARTICLES','MONTANT HT','ÉTAT'];body=data.map(o=>`<tr><td>${fmt(o.order_date)}</td><td><b>${esc(o.order_number)}</b></td><td>${esc(o.supplier_name)}</td><td>${esc(o.items||'—')}</td><td>${money(o.subtotal||0)} ${esc(o.currency_code)}</td><td><select class="filter-control order-status" data-id="${o.purchase_order_id}"><option value="${o.status}">${esc(o.status)}</option>${['DRAFT','SENT','CONFIRMED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED'].filter(s=>s!==o.status).map(s=>`<option value="${s}">${s}</option>`).join('')}</select></td></tr>`).join('')}
    if(kind==='quotes'){headers=['DATE','N° DEMANDE','FOURNISSEURS','ARTICLES','RÉPONSES','ÉTAT','ACTION'];body=data.map(q=>`<tr><td>${fmt(q.request_date)}</td><td><b>${esc(q.request_number)}</b></td><td>${q.suppliers_count}</td><td>${q.line_count}</td><td>${q.responses_received} / ${q.suppliers_count}</td><td>${status(q.status)}</td><td><button class="btn btn-small record-quote" data-id="${q.quote_request_id}">Saisir une réponse</button></td></tr>`).join('')}
    if(kind==='supervision'){headers=['AGENT','RÔLE','UNITÉS AFFECTÉES','MOUVEMENTS','ENTRÉES %','MAINTENANCES','TERMINÉES %','DÉFECTUEUX','NOTE DU JOUR','AVIS','ACTION'];body=data.map(u=>`<tr><td><b>${esc(u.full_name)}</b><br><small>${esc(u.matricule)}</small></td><td>${u.role_code==='STOREKEEPER'?'Magasinier':'Maintenancier'}</td><td>${u.assigned_units}</td><td>${u.movements} <small>(${u.entries} entrée / ${u.exits} sortie)</small></td><td>${u.entry_percent}%</td><td>${u.planned+u.completed}</td><td>${u.maintenance_completion_percent}%</td><td>${u.defective}</td><td>${u.rating?`${u.rating}/5`:'—'}</td><td>${esc(u.opinion||'—')}</td><td><button class="btn btn-small btn-primary score-agent" data-id="${u.user_id}" data-name="${esc(u.full_name)}">Noter aujourd’hui</button></td></tr>`).join('')}
    if(kind==='audit'){headers=['DATE','UTILISATEUR','ACTION','OBJET','ID','CONTEXTE'];body=data.map(log=>`<tr><td>${fmtDateTime(log.occurred_at)}</td><td>${esc(log.full_name||'Système')} · ${esc(log.matricule||'')}</td><td><span class="status info">${esc(log.action_code)}</span></td><td>${esc(log.entity_name)}</td><td>${esc(log.entity_id||'—')}</td><td class="cell-wrap">${esc(typeof log.details==='string'?log.details:JSON.stringify(log.details||{}))}</td></tr>`).join('')}
    if(kind==='users'){headers=['UTILISATEUR','MATRICULE','E-MAIL','DÉPARTEMENT','RÔLE','MFA','ÉTAT','ACTIONS'];body=data.map(u=>`<tr><td><b>${esc(u.full_name)}</b></td><td>${esc(u.matricule)}</td><td>${esc(u.email||'—')}</td><td><button class="btn btn-small user-department" data-id="${u.user_id}" data-name="${esc(u.full_name)}" data-department="${esc(u.department_name||'')}">${esc(u.department_name||'Renseigner')}</button></td><td><select class="filter-control user-role" data-id="${u.user_id}">${['ADMIN','STOREKEEPER','MAINTAINER','SUPERVISOR'].map(code=>`<option value="${code}" ${u.role_code===code?'selected':''}>${code}</option>`).join('')}</select></td><td>${status(u.mfa_enabled?'MFA actif':'MFA à configurer')}</td><td>${status(u.is_active?'Actif':'Désactivé')}</td><td><button class="btn btn-small reset-mfa" data-id="${u.user_id}">Réinit. MFA</button><button class="btn btn-small toggle-user" data-id="${u.user_id}" data-active="${u.is_active?1:0}">${u.is_active?'Bloquer':'Débloquer'}</button></td></tr>`).join('')}
    setTable(headers);b.innerHTML=body||`<tr><td colspan="${headers.length}">Aucun résultat pour ces filtres.</td></tr>`;b.querySelectorAll('tr').forEach((row,index)=>{if(data[index])row.__record=data[index]});document.querySelector('#row-count').textContent=`${data.length} résultat(s)`;document.querySelector('#period-summary').textContent=summary(data);bindRows();
  }

  function drawOversight(result){const card=document.createElement('section');card.id='oversight-extra';card.className='card mb12';const existing=document.querySelector('#oversight-extra');if(existing)existing.remove();document.querySelector('#oversight-movements')?.remove();const totals=result.personnel.reduce((a,u)=>({people:a.people+1,units:a.units+Number(u.assigned_units||0),moves:a.moves+Number(u.movements||0),completed:a.completed+Number(u.completed||0)}),{people:0,units:0,moves:0,completed:0});document.querySelector('#module-kpis').innerHTML=[['Agents suivis',totals.people],['Matériels affectés',totals.units],['Mouvements sur période',totals.moves],['Maintenances terminées',totals.completed]].map(([label,value])=>`<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-detail">${result.from} → ${result.to}</div></article>`).join('');let graph=document.querySelector('#oversight-chart');if(!graph){graph=document.createElement('section');graph.id='oversight-chart';graph.className='card mb12';document.querySelector('#module-kpis').after(graph)}const maxMoves=Math.max(1,...result.personnel.map(u=>Number(u.movements)||0));graph.innerHTML=`<div class="card-head"><div><h2>Comparaison de l’activité des équipes</h2><small>Mouvements enregistrés et taux de clôture des maintenances</small></div></div><div class="card-body bar-list">${result.personnel.map(u=>`<div class="oversight-agent-row"><b>${esc(u.full_name)}</b><span>Mouvements · ${u.movements}</span><div class="oversight-track"><i style="width:${Math.min(100,100*(Number(u.movements)||0)/maxMoves)}%"></i></div><span>Maintenances terminées · ${u.maintenance_completion_percent}%</span></div>`).join('')}</div>`;card.innerHTML=`<div class="card-head"><div><h2>Notes journalières</h2><small>Historique complet des avis du ${esc(result.from)} au ${esc(result.to)}</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>AGENT</th><th>RÔLE</th><th>NOTE / 5</th><th>AVIS</th><th>SUPERVISEUR</th></tr></thead><tbody>${result.reviews.map(r=>`<tr><td>${fmt(r.review_date)}</td><td>${esc(r.employee_name)} · ${esc(r.matricule)}</td><td>${r.role_code==='STOREKEEPER'?'Magasinier':'Maintenancier'}</td><td><span class="status ${r.rating>=4?'ok':r.rating<=2?'bad':'low'}">${r.rating}/5</span></td><td class="cell-wrap">${esc(r.opinion)}</td><td>${esc(r.supervisor_name)}</td></tr>`).join('')||'<tr><td colspan="6">Aucune notation sur cette période.</td></tr>'}</tbody></table></div>`;document.querySelector('#period-summary-card').before(card);const movement=document.createElement('section');movement.id='oversight-movements';movement.className='card mb12';movement.innerHTML=`<div class="card-head"><div><h2>Traçabilité des mouvements</h2><small>Chaque badge indique la nature de l’opération</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>BADGE</th><th>RÉFÉRENCE</th><th>MATÉRIEL</th><th>QTÉ</th><th>ORIGINE → DESTINATION</th><th>AGENT</th><th>DÉTAIL</th></tr></thead><tbody>${result.movements.map(m=>`<tr><td>${fmtDateTime(m.movement_date)}</td><td><span class="status ${m.movement_type==='IN'?'ok':m.movement_type==='OUT'?'bad':'info'}">${esc(m.badge)}</span></td><td>${esc(m.movement_number)}</td><td>${esc(m.material_code)} · ${esc(m.designation)}</td><td>${m.quantity}</td><td>${esc(m.source_location||'—')} → ${esc(m.destination_location||'—')}</td><td>${esc(m.performed_by||'—')}</td><td>${esc(m.notes||m.document_reference||'—')}</td></tr>`).join('')||'<tr><td colspan="8">Aucun mouvement sur la période.</td></tr>'}</tbody></table></div>`;document.querySelector('#period-summary-card').before(movement);document.querySelectorAll('.score-agent').forEach(button=>button.addEventListener('click',()=>{const today=new Date().toISOString().slice(0,10);openModal(`Notation du jour · ${button.dataset.name}`,`<div class="form-grid">${field('Date','reviewDate',today,'date')}${select('Note sur 5','rating','<option value="5">5 · Excellent</option><option value="4">4 · Très bien</option><option value="3">3 · Satisfaisant</option><option value="2">2 · À améliorer</option><option value="1">1 · Insuffisant</option>')}${textarea('Avis et observations','opinion')}</div>`,async data=>{await MatApi.request('/api/supervision/reviews',{method:'POST',body:{employeeUserId:+button.dataset.id,reviewDate:data.reviewDate,rating:+data.rating,opinion:data.opinion}});MatApi.toast('Évaluation journalière enregistrée.');await load()});document.querySelector('#f-reviewDate').value=today}))}
  function status(text){let cls=({IN:'ok',Entrée:'ok',AVAILABLE:'ok',Disponible:'ok',OUT:'bad',Sortie:'bad',DAMAGED:'bad',Endommagé:'bad',Stock:'low',PLANNED:'low',En:'info',CONFIRMED:'info',SENT:'info',RETIRED:'neutral',Actif:'ok',Désactivé:'neutral'}[text]||'info');return `<span class="status ${cls}">${esc(text)}</span>`}
  function fmt(value){return value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(value)):''}
  function fmtDateTime(value){return value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):''}
  function money(value){return new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(Number(value)||0)}
  function summary(data){if(!data.length)return 'Aucun enregistrement ne correspond à la période et aux filtres sélectionnés.';if(kind==='materials'){const low=data.filter(x=>Number(x.below_minimum)).length,units=data.reduce((n,x)=>n+Number(x.total_quantity),0);return `Le résultat filtré contient ${data.length} référence(s) et ${units} unité(s). ${low} référence(s) sont sous le seuil de réapprovisionnement.`}if(kind==='movements'){const ins=data.filter(x=>x.movement_type==='IN').length,outs=data.filter(x=>x.movement_type==='OUT').length;return `${data.length} ligne(s) de mouvement affichées. ${ins} entrée(s), ${outs} sortie(s) et ${data.length-ins-outs} transfert(s).`}if(kind==='maintenance'){const open=data.filter(x=>['PLANNED','IN_PROGRESS'].includes(x.status)).length;return `${data.length} intervention(s) dans les filtres sélectionnés; ${open} restent planifiées ou en cours.`}if(kind==='users')return `${data.length} compte(s) correspondent à la recherche. ${data.filter(x=>x.mfa_enabled).length} ont terminé leur enrôlement MFA.`;return `${data.length} enregistrement(s) affiché(s) pour les critères sélectionnés.`}
  function drawReports(d){const k=d.kpis;document.querySelector('#module-kpis').innerHTML=`<article class="kpi"><div class="kpi-label">Unités en stock</div><div class="kpi-value">${k.units}</div><div class="kpi-detail">${k.references} références</div></article><article class="kpi"><div class="kpi-label">Alertes de stock</div><div class="kpi-value">${k.lowStock}</div><div class="kpi-detail">Sous le seuil minimum</div></article><article class="kpi"><div class="kpi-label">Mouvements période</div><div class="kpi-value">${k.movements}</div><div class="kpi-detail">${k.entries} entrées · ${k.exits} sorties</div></article><article class="kpi"><div class="kpi-label">Maintenances ouvertes</div><div class="kpi-value">${k.maintenance}</div><div class="kpi-detail">À traiter ou planifiées</div></article>`;document.querySelector('#table-head').innerHTML='<th>RÉFÉRENCE</th><th>MATÉRIEL</th><th>CATÉGORIE</th><th>QUANTITÉ</th><th>SEUIL</th><th>ÉTAT</th>';const body=document.querySelector('#table-body');body.innerHTML=d.materials.map(m=>`<tr><td>${esc(m.material_code)}</td><td><b>${esc(m.designation)}</b></td><td>${esc(m.category_name)}</td><td>${m.total_quantity}</td><td>${m.minimum_stock}</td><td>${status(m.below_minimum?'Stock faible':m.operational_status)}</td></tr>`).join('');body.querySelectorAll('tr').forEach((row,index)=>{row.__record=d.materials[index]});document.querySelector('#period-summary').textContent=d.summary;document.querySelector('#row-count').textContent=`Période : ${d.period.from} – ${d.period.to}`}
  async function lookupsForCreate(){const stockUrl=kind==='maintenance'?'/api/maintenance/available-materials':'/api/materials';const responses=await Promise.all([MatApi.request('/api/categories'),MatApi.request('/api/locations'),MatApi.request(stockUrl),MatApi.request('/api/services')]);lookups.categories=responses[0].categories;lookups.locations=responses[1].locations;lookups.materials=responses[2].materials;lookups.services=responses[3].services}
  function field(label,name,placeholder='',type='text',required=true){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" placeholder="${placeholder}" type="${type}" ${required?'required':''}></div>`}
  function textarea(label,name,required=true){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="3" maxlength="5000" ${required?'required':''}></textarea></div>`}
  function select(label,name,options,required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${options}</select></div>`}
  async function openCreate(){await lookupsForCreate();let title='',html='';
    if(kind==='materials'){title='Ajouter un matériel';html=`<div class="form-grid"><div class="field full"><label for="f-mercurialeSearch">Rechercher dans la mercuriale</label><input id="f-mercurialeSearch" type="search" placeholder="Saisir un code ou une désignation (2 caractères minimum)" autocomplete="off"><small class="muted-small" id="mercuriale-search-status">La recherche porte sur le code, la désignation et la catégorie.</small></div>${select('Article de la mercuriale','mercurialeItemId','<option value="">Saisissez au moins 2 caractères pour rechercher</option>')}<div class="field"><label>Code matériel</label><input id="f-materialCode" value="—" readonly></div><div class="field"><label>Désignation</label><input id="f-designation" readonly></div><div class="field"><label>Catégorie</label><input id="f-categoryName" readonly></div>${select('Emplacement de stockage','locationId','<option value="">Choisissez d’abord un article</option>'+lookups.locations.filter(l=>l.category_id).map(l=>`<option value="${l.location_id}" data-category="${l.category_id}">${esc(l.location_name)}</option>`).join(''))}${field('Marque','brand','Marque','text',false)}${field('Modèle','model','Modèle','text',false)}${field('Numéro de série (facultatif)','serialNumber','Numéro de série','text',false)}${field('Adresse MAC (facultatif)','macAddress','00:11:22:33:44:55','text',false)}<div id="minimum-stock-field">${field('Seuil minimum','minimumStock','0','number')}</div><div class="field full" id="similar-material-notice" hidden></div>${field('Description','description','Description','text',false)}</div><p class="muted-small">L’emplacement est associé à la catégorie et sera conservé sur la fiche du matériel.</p>`}
    if(kind==='movements'){title='Enregistrer un mouvement';html=`<div class="form-grid">${select('Type','type','<option value="IN">Entrée</option><option value="OUT">Sortie</option><option value="TRANSFER">Transfert</option>')}${select('Matériel','materialId',lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} — ${esc(m.designation)}</option>`).join(''))}${field('Quantité','quantity','Quantité','number')}${select('Emplacement source','sourceLocationId',`<option value="">Aucun</option>`+lookups.locations.map(l=>`<option value="${l.location_id}">${esc(l.location_name)}</option>`).join(''),false)}${select('Emplacement destination','destinationLocationId',`<option value="">Aucun</option>`+lookups.locations.map(l=>`<option value="${l.location_id}">${esc(l.location_name)}</option>`).join(''),false)}${field('Destinataire','recipientName','Nom ou service','text',false)}${field('Référence document','documentReference','Bon / décharge','text',false)}</div>`}
    if(kind==='allocations'){title='Créer une dotation';html=`<div class="form-grid">${select('Service bénéficiaire','serviceId',lookups.services.map(s=>`<option value="${s.service_id}">${esc(s.service_name)}</option>`).join(''))}${select('Emplacement de sortie','sourceLocationId',lookups.locations.map(l=>`<option value="${l.location_id}">${esc(l.location_name)}</option>`).join(''))}${select('Matériel','materialId',lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} — ${esc(m.designation)}</option>`).join(''))}${field('Quantité','quantity','1','number')}${field('Bénéficiaire','recipientName','Nom du récipiendaire')}${select('Type de pièce','recipientIdType','<option value="MATRICULE">Matricule</option><option value="CNI">Numéro de CNI</option>')}${field('Matricule ou numéro de CNI','recipientIdNumber','Identifiant du bénéficiaire')}${field('N° de décharge','receiptReference','Référence','text',false)}</div>`}
    if(kind==='maintenance'){title='Nouvelle intervention';const technicianOptions=role==='ADMIN'?(await MatApi.request('/api/maintenance/technicians')).technicians.map(t=>`<option value="${t.user_id}">${esc(t.full_name)} · ${esc(t.matricule)}</option>`).join(''):'';html=`<div class="form-grid">${select('Mode','mode','<option value="PLANNED">Planifier à une date</option><option value="IMMEDIATE">Commencer immédiatement</option>')}${select('Matériel','materialId',lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} — ${esc(m.designation)}</option>`).join(''))}${select('Type','type','<option value="PREVENTIVE">Préventive</option><option value="REPAIR">Réparation</option><option value="DIAGNOSTIC">Diagnostic</option><option value="INSTALLATION">Installation</option><option value="OTHER">Autre</option>')}<div class="field" id="maintenance-schedule-field">${field('Date et heure','scheduledAt','','datetime-local')}</div>${role==='ADMIN'?select('Maintenancier affecté','technicianId','<option value="">Choisir un maintenancier</option>'+technicianOptions,false):'<p class="muted-small">Intervention affectée à votre compte; le matériel sera transféré automatiquement depuis le stock magasinier.</p>'}${field('Durée (minutes)','durationMinutes','120','number',false)}<div class="field full"><label>Description du problème / intervention</label><textarea name="problemDescription" rows="3"></textarea></div></div><p class="muted-small" id="maintenance-mode-help">Le maintenancier affecté recevra un e-mail cinq minutes avant l’heure prévue. Activez les bips dans la barre supérieure.</p>`}
    if(kind==='suppliers'){title='Ajouter un fournisseur';html=`<div class="form-grid">${field('Nom de l’entreprise','name','Entreprise')}${field('Personne à contacter','contactName','Nom','text',false)}${field('Adresse e-mail','email','nom@fournisseur.cm','email',false)}${field('Téléphone','phone','+237…','tel',false)}${field('Adresse','address','Adresse','text',false)}${field('Spécialité','specialty','Informatique, réseau…','text',false)}</div>`}
    if(kind==='orders'){title='Créer un bon de commande';html=`<div class="form-grid">${select('Fournisseur','supplierId',(await MatApi.request('/api/suppliers')).suppliers.map(s=>`<option value="${s.supplier_id}">${esc(s.supplier_name)}</option>`).join(''))}${select('Matériel','materialId',lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} — ${esc(m.designation)}</option>`).join(''))}${field('Quantité','quantity','1','number')}${field('Prix unitaire (FCFA)','unitPrice','0','number')}${field('Livraison prévue','expectedDate','','date',false)}</div>`}
    if(kind==='quotes'){title='Créer une demande de prix';html=`<div class="form-grid">${field('Référence (facultatif)','requestNumber','DP-2026-001','text',false)}<div class="field"><label for="quote-suppliers">Fournisseurs à consulter</label><select id="quote-suppliers" name="supplierIds" multiple size="4" required>${(await MatApi.request('/api/suppliers')).suppliers.map(s=>`<option value="${s.supplier_id}">${esc(s.supplier_name)}</option>`).join('')}</select></div>${select('Matériel','materialId',lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} — ${esc(m.designation)}</option>`).join(''))}${field('Quantité demandée','quantity','1','number')}${field('Date limite de réponse','requiredBy','','date',false)}<div class="field full"><label for="quote-notes">Notes</label><textarea id="quote-notes" name="notes" rows="3"></textarea></div></div><p class="muted-small">Cette opération enregistre un brouillon et ne transmet aucun courriel aux fournisseurs.</p>`}
    if(kind==='users'){title='Créer un compte utilisateur';html=`<div class="form-grid">${field('Matricule','matricule','Ex. MAG-045')}${field('Nom complet','fullName','Nom Prénom')}${field('E-mail','email','personne@service.cm','email')}${field('Département','departmentName','Ex. Informatique','text',false)}${select('Rôle','roleCode','<option value="STOREKEEPER">Magasinier</option><option value="MAINTAINER">Maintenancier</option><option value="SUPERVISOR">Superviseur</option><option value="ADMIN">Administrateur</option>')}${field('Mot de passe initial','initialPassword','12 caractères minimum','password')}</div><p class="muted-small">Communiquez ce mot de passe initial par un canal contrôlé. L’utilisateur devra configurer son TOTP avant d’accéder à l’application.</p>`}
    if(kind==='materials') {openModal(title,html,async data=>{data.minimumStock=Number(data.minimumStock);data.locationId=Number(data.locationId);const result=await MatApi.request('/api/materials',{method:'POST',body:data});MatApi.toast(result.merged?`Nouvelle fiche ${result.materialCode} enregistrée; quantité augmentée de 1 pour ${result.matchedDesignation} (${result.similarityPercent} % de similarité).`:`Matériel ajouté avec le code ${result.materialCode}.`);await load()});const search=document.querySelector('#f-mercurialeSearch'),selectItem=document.querySelector('#f-mercurialeItemId'),searchStatus=document.querySelector('#mercuriale-search-status'),thresholdField=document.querySelector('#minimum-stock-field'),thresholdInput=document.querySelector('#f-minimumStock'),similarNotice=document.querySelector('#similar-material-notice'),submitButton=document.querySelector('#module-form [type=submit]');let searchTimer,searchSequence=0,matchSequence=0;function resetSimilarity(){matchSequence++;thresholdField.hidden=false;thresholdInput.required=true;thresholdInput.value='';similarNotice.hidden=true;similarNotice.textContent='';submitButton.disabled=false}search.addEventListener('input',()=>{clearTimeout(searchTimer);resetSimilarity();const query=search.value.trim(),sequence=++searchSequence;if(query.length<2){selectItem.disabled=false;selectItem.innerHTML='<option value="">Saisissez au moins 2 caractères pour rechercher</option>';searchStatus.textContent='La recherche porte sur le code, la désignation et la catégorie.';return}selectItem.disabled=false;selectItem.innerHTML='<option value="">Recherche en cours…</option>';searchStatus.textContent='Recherche dans la mercuriale…';searchTimer=setTimeout(async()=>{try{const result=await MatApi.request(`/api/mercuriale?q=${encodeURIComponent(query)}`);if(sequence!==searchSequence)return;const items=result.items||[];selectItem.innerHTML=items.length?'<option value="">Choisir une référence ('+items.length+')</option>'+items.map(i=>`<option value="${i.mercuriale_item_id}" data-code="${esc(i.material_code)}" data-designation="${esc(i.designation)}" data-category="${i.category_id}">${esc(i.category_name)} · ${esc(i.material_code)} · ${esc(i.designation)}</option>`).join(''):'<option value="">Aucune référence trouvée</option>';selectItem.disabled=false;searchStatus.textContent=items.length?`${items.length} référence(s) trouvée(s). Sélectionnez celle à enregistrer.`:'Aucune référence ne correspond à cette recherche.'}catch(error){if(sequence!==searchSequence)return;selectItem.innerHTML='<option value="">Recherche impossible</option>';searchStatus.textContent=error.message}},250)});selectItem.addEventListener('change',async e=>{const option=e.target.selectedOptions[0],categoryId=option.dataset.category;document.querySelector('#f-materialCode').value=option.dataset.code||'';document.querySelector('#f-designation').value=option.dataset.designation||'';document.querySelector('#f-categoryName').value=lookups.categories.find(c=>String(c.category_id)===categoryId)?.category_name||'';const locationSelect=document.querySelector('#f-locationId'),categoryLocations=lookups.locations.filter(l=>String(l.category_id)===categoryId);locationSelect.innerHTML='<option value="">Choisir un emplacement</option>'+categoryLocations.map(l=>`<option value="${l.location_id}">${esc(l.location_name)}</option>`).join('');locationSelect.disabled=!categoryLocations.length;resetSimilarity();if(!option.value)return;const sequence=++matchSequence;submitButton.disabled=true;similarNotice.hidden=false;similarNotice.textContent='Vérification des désignations existantes…';try{const result=await MatApi.request(`/api/materials/match?mercurialeItemId=${encodeURIComponent(option.value)}`);if(sequence!==matchSequence)return;const match=result.match;if(match){thresholdField.hidden=true;thresholdInput.required=false;thresholdInput.value='0';similarNotice.innerHTML=`Une référence proche existe : <b>${esc(match.materialCode)} · ${esc(match.designation)}</b> (${match.similarityPercent} %). L’enregistrement ajoutera 1 unité à son stock, sans créer de seuil séparé.`}else{thresholdField.hidden=false;thresholdInput.required=true;similarNotice.textContent='Aucune désignation assez proche : vous pouvez définir le seuil de cette nouvelle référence.'}submitButton.disabled=false}catch(error){if(sequence!==matchSequence)return;thresholdField.hidden=false;thresholdInput.required=true;similarNotice.textContent=`La vérification a échoué : ${error.message} Le serveur revérifiera la similarité au moment de l’enregistrement.`;submitButton.disabled=false}});return}
    openModal(title,html,async data=>{
      if(kind==='materials'){data.minimumStock=Number(data.minimumStock);await MatApi.request('/api/materials',{method:'POST',body:data})}
      if(kind==='movements'){data.quantity=Number(data.quantity);data.materialId=Number(data.materialId);data.sourceLocationId=data.sourceLocationId?Number(data.sourceLocationId):null;data.destinationLocationId=data.destinationLocationId?Number(data.destinationLocationId):null;await MatApi.request('/api/movements',{method:'POST',body:data})}
      if(kind==='allocations'){await MatApi.request('/api/allocations',{method:'POST',body:{serviceId:+data.serviceId,sourceLocationId:+data.sourceLocationId,recipientName:data.recipientName,recipientIdType:data.recipientIdType,recipientIdNumber:data.recipientIdNumber,receiptReference:data.receiptReference,lines:[{materialId:+data.materialId,quantity:+data.quantity}]}})}
      if(kind==='maintenance'){data.materialId=+data.materialId;data.technicianId=data.technicianId?+data.technicianId:null;data.durationMinutes=data.durationMinutes?+data.durationMinutes:null;if(data.mode==='PLANNED'&&!data.scheduledAt)throw new Error('Choisissez la date et l’heure de l’intervention.');if(data.mode==='PLANNED')data.scheduledAt=new Date(data.scheduledAt).toISOString();await MatApi.request('/api/maintenance',{method:'POST',body:data});MatApi.toast(data.mode==='IMMEDIATE'?'Intervention démarrée et attribuée.':'Intervention planifiée.')}
      if(kind==='suppliers')await MatApi.request('/api/suppliers',{method:'POST',body:data});
      if(kind==='orders'){await MatApi.request('/api/orders',{method:'POST',body:{supplierId:+data.supplierId,expectedDate:data.expectedDate||null,lines:[{materialId:+data.materialId,quantity:+data.quantity,unitPrice:+data.unitPrice}]}})}
      if(kind==='quotes'){await MatApi.request('/api/quote-requests',{method:'POST',body:{requestNumber:data.requestNumber||undefined,requiredBy:data.requiredBy||null,notes:data.notes,supplierIds:data.supplierIds,lines:[{materialId:+data.materialId,quantity:+data.quantity}]}})}
      if(kind==='users')await MatApi.request('/api/users',{method:'POST',body:data});
      if(kind!=='maintenance')MatApi.toast('Enregistrement effectué.');await load();
    });
    if(kind==='maintenance'){const mode=document.querySelector('#f-mode'),schedule=document.querySelector('#maintenance-schedule-field'),date=document.querySelector('#f-scheduledAt'),technician=document.querySelector('#f-technicianId'),help=document.querySelector('#maintenance-mode-help');const syncMode=()=>{const planned=mode.value==='PLANNED';schedule.hidden=!planned;date.required=planned;if(technician)technician.required=true;help.textContent=planned?'Le maintenancier affecté recevra un e-mail cinq minutes avant l’heure prévue. Activez les bips dans la barre supérieure.':'L’intervention passera immédiatement à l’état « En cours » et vous sera attribuée.'};mode.addEventListener('change',syncMode);syncMode()}
  }
  function openModal(title,body,onSubmit){const host=document.querySelector('#modal-root');host.innerHTML=`<div class="auth-bg modal-backdrop"><section class="auth-card"><h1>${esc(title)}</h1><form id="module-form">${body}<div class="title-actions"><button class="btn" type="button" id="cancel-modal">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form></section></div>`;host.querySelector('#cancel-modal').onclick=()=>host.replaceChildren();host.querySelector('#module-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.currentTarget));if(kind==='quotes')data.supplierIds=[...e.currentTarget.querySelector('#quote-suppliers').selectedOptions].map(option=>Number(option.value));await onSubmit(data);host.replaceChildren()}catch(error){showMessage(error.message,true);button.disabled=false}})}
  async function recordQuoteResponse(id){try{const detail=await MatApi.request(`/api/quote-requests/${id}`);const pending=detail.suppliers.filter(s=>s.response_status==='PENDING');if(!pending.length)return showMessage('Tous les fournisseurs ont répondu.');const supplierOptions=pending.map(s=>`<option value="${s.supplier_id}">${esc(s.supplier_name)}</option>`).join('');const lineFields=detail.lines.map(line=>`<div class="card profile-card"><b>${esc(line.material_code)} · ${esc(line.designation)}</b><p>Quantité demandée : ${line.requested_quantity}</p><input type="hidden" name="lineId_${line.quote_request_line_id}" value="${line.quote_request_line_id}">${field('Prix unitaire FCFA',`price_${line.quote_request_line_id}`,'0','number')}${field('Quantité proposée',`quantity_${line.quote_request_line_id}`,String(line.requested_quantity),'number')}${field('Taxe %',`tax_${line.quote_request_line_id}`,'0','number')}${field('Délai (jours)',`days_${line.quote_request_line_id}`,'','number',false)}</div>`).join('');openModal(`Réponse fournisseur · ${detail.request.request_number}`,`<div class="form-grid">${select('Fournisseur','supplierId',supplierOptions)}${field('Référence du devis','quoteNumber','Référence fournisseur','text',false)}${field('Valide jusqu’au','validUntil','','date',false)}</div>${lineFields}`,async data=>{const lines=detail.lines.map(line=>({requestLineId:line.quote_request_line_id,unitPrice:+data[`price_${line.quote_request_line_id}`],quantity:+data[`quantity_${line.quote_request_line_id}`],taxRate:+data[`tax_${line.quote_request_line_id}`]||0,deliveryDays:data[`days_${line.quote_request_line_id}`]?+data[`days_${line.quote_request_line_id}`]:null}));await MatApi.request(`/api/quote-requests/${id}/quotes`,{method:'POST',body:{supplierId:+data.supplierId,quoteNumber:data.quoteNumber||null,validUntil:data.validUntil||null,lines}});MatApi.toast('Réponse fournisseur enregistrée.');await load()})}catch(error){showMessage(error.message,true)}}
  async function manageMaintenanceParts(button){try{const id=button.dataset.id,number=button.dataset.number,result=await MatApi.request(`/api/maintenance/${id}/parts`),rows=result.parts||[];const history=rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>PIÈCE</th><th>QUANTITÉ</th><th>EMPLACEMENT</th><th>AGENT</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${fmt(p.movement_date)}</td><td>${esc(p.material_code)} · ${esc(p.designation)}</td><td>${p.quantity}</td><td>${esc(p.location_name)}</td><td>${esc(p.issued_by||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="summary-text">Aucune pièce sortie pour cette intervention.</p>';const materialOptions=lookups.materials.map(m=>`<option value="${m.material_id}">${esc(m.material_code)} · ${esc(m.designation)} (${m.total_quantity} en stock)</option>`).join('');const locationOptions=lookups.locations.map(l=>`<option value="${l.location_id}">${esc(l.location_name)}</option>`).join('');const canConsume=['PLANNED','IN_PROGRESS'].includes(button.dataset.status);const form=canConsume?`<hr><h2>Enregistrer une sortie</h2><p class="muted-small">La quantité sera retirée de l’emplacement choisi et rattachée à cette intervention.</p><div class="form-grid">${select('Matériel','materialId',materialOptions)}${select('Emplacement source','locationId',locationOptions)}${field('Quantité','quantity','1','number')}${field('Note','notes','Facultatif','text',false)}</div>`:'<p class="muted-small">Intervention clôturée : consultation de l’historique uniquement.</p>';openModal(`Pièces consommées · ${number}`,`${history}${form}`,async data=>{if(!canConsume)return;await MatApi.request(`/api/maintenance/${id}/parts`,{method:'POST',body:{materialId:+data.materialId,locationId:+data.locationId,quantity:+data.quantity,notes:data.notes}});MatApi.toast('Sortie de pièce enregistrée.');await load()});if(!canConsume)document.querySelector('#module-form [type=submit]').hidden=true}catch(error){showMessage(error.message,true)}}
  function executeMaintenance(record){const readOnly=`<p class="muted-small">Matériel : <b>${esc(record.material_code)}</b> · ${esc(record.designation)}<br>Maintenancier : <b>${esc(record.technician_matricule||'—')} · ${esc(record.technician||'—')}</b><br>Département : <b>${esc(record.technician_department||'Non renseigné')}</b></p>`;const form=`<div class="form-grid">${textarea('Diagnostic','diagnosis')}${textarea('Actions posées','actionsTaken')}${textarea('Commentaires','comments',false)}${select('Conclusion','conclusion','<option value="">Choisir une conclusion</option><option value="FUNCTIONAL">Fonctionnel</option><option value="DEFECTIVE">Défectueux</option>')}</div><p class="muted-small">L’enregistrement clôturera l’intervention. Une conclusion « Défectueux » marquera le matériel comme endommagé.</p>`;openModal(`Exécution · ${record.maintenance_number}`,readOnly+form,async data=>{await MatApi.request(`/api/maintenance/${record.maintenance_id}/status`,{method:'PATCH',body:{status:'COMPLETED',...data}});MatApi.toast('Compte-rendu enregistré; intervention terminée.');await load()});document.querySelector('#module-form [type="submit"]').textContent='Enregistrer et terminer'}
  function showMaintenanceDetails(record){const pairs=[['Code matériel',record.material_code],['Désignation',record.designation],['Diagnostic',record.diagnosis],['Actions posées',record.actions_taken],['Commentaires',record.comments],['Conclusion',record.conclusion==='FUNCTIONAL'?'Fonctionnel':record.conclusion==='DEFECTIVE'?'Défectueux':null],['Matricule maintenancier',record.technician_matricule],['Nom maintenancier',record.technician],['Département maintenancier',record.technician_department],['Exécuté par',record.executed_by_name?`${record.executed_by_matricule} · ${record.executed_by_name}`:null],['Date planifiée',record.scheduled_at],['Début réel',record.started_at],['Fin',record.completed_at],['État',record.status]];const content=`<div class="maintenance-detail-grid">${pairs.map(([label,value])=>`<div><b>${esc(label)}</b><span>${esc(value||'—')}</span></div>`).join('')}</div>`;openModal(`Détails · ${record.maintenance_number}`,content,async()=>{});document.querySelector('#module-form [type="submit"]').hidden=true}
  function bindRows(){document.querySelectorAll('.maintenance-row').forEach(row=>{const record=rows.find(item=>String(item.maintenance_id)===row.dataset.id);row.addEventListener('click',event=>{if(event.target.closest('button'))return;if(record&&['PLANNED','IN_PROGRESS'].includes(record.status))executeMaintenance(record);else if(record)showMaintenanceDetails(record)});row.addEventListener('keydown',event=>{if(event.target!==row||!['Enter',' '].includes(event.key))return;event.preventDefault();if(record&&['PLANNED','IN_PROGRESS'].includes(record.status))executeMaintenance(record);else if(record)showMaintenanceDetails(record)});row.querySelector('.maintenance-execute')?.addEventListener('click',event=>{event.stopPropagation();if(record)executeMaintenance(record)});row.querySelector('.maintenance-details')?.addEventListener('click',event=>{event.stopPropagation();if(record)showMaintenanceDetails(record)})});document.querySelectorAll('.maintenance-parts').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();manageMaintenanceParts(button)}));document.querySelectorAll('.user-department').forEach(button=>button.addEventListener('click',()=>{openModal(`Département · ${button.dataset.name}`,field('Département','departmentName','Ex. Informatique','text',false),async data=>{await MatApi.request(`/api/users/${button.dataset.id}`,{method:'PATCH',body:{departmentName:data.departmentName}});MatApi.toast('Département mis à jour.');await load()});document.querySelector('#f-departmentName').value=button.dataset.department||''}));document.querySelectorAll('.status-select').forEach(select=>select.addEventListener('change',async()=>{try{await MatApi.request(`/api/materials/${select.dataset.id}/status`,{method:'PATCH',body:{status:select.value}});MatApi.toast('Statut modifié.');await load()}catch(error){showMessage(error.message,true)}}));document.querySelectorAll('.maintenance-status').forEach(select=>select.addEventListener('change',async()=>{try{await MatApi.request(`/api/maintenance/${select.dataset.id}/status`,{method:'PATCH',body:{status:select.value}});await load()}catch(error){showMessage(error.message,true)}}));document.querySelectorAll('.order-status').forEach(select=>select.addEventListener('change',async()=>{try{await MatApi.request(`/api/orders/${select.dataset.id}/status`,{method:'PATCH',body:{status:select.value}});await load()}catch(error){showMessage(error.message,true)}}));document.querySelectorAll('.user-role').forEach(select=>select.addEventListener('change',async()=>{try{await MatApi.request(`/api/users/${select.dataset.id}`,{method:'PATCH',body:{roleCode:select.value}});MatApi.toast('Rôle mis à jour.')}catch(error){showMessage(error.message,true);await load()}}));document.querySelectorAll('.toggle-user').forEach(button=>button.addEventListener('click',async()=>{try{await MatApi.request(`/api/users/${button.dataset.id}`,{method:'PATCH',body:{isActive:button.dataset.active!=='1'}});await load()}catch(error){showMessage(error.message,true)}}));document.querySelectorAll('.reset-mfa').forEach(button=>button.addEventListener('click',()=>openModal('Réinitialiser le second facteur','Confirmez avec votre mot de passe et votre TOTP administrateur.',`<div class="field"><label>Mot de passe administrateur</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>Code TOTP</label><input name="totpCode" inputmode="numeric" maxlength="6" required></div>`,async data=>{await MatApi.request(`/api/users/${button.dataset.id}/reset-mfa`,{method:'POST',body:data});MatApi.toast('MFA réinitialisé; l’utilisateur devra le réenrôler.');await load()})));document.querySelectorAll('.record-quote').forEach(button=>button.addEventListener('click',()=>recordQuoteResponse(button.dataset.id)))}
  function exportCsv(){const exportRows=kind==='reports'?rows.materials||[]:rows;if(!exportRows.length)return;const vals=exportRows.map(row=>Object.values(row));const heads=Object.keys(exportRows[0]);const csv='\ufeff'+[heads,...vals].map(line=>line.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`mat-manage-${kind}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  return{mount:async pageKind=>{kind=pageKind;await bootstrap()}};
})();
